/**
 * Offline cache.
 *
 * The hosted build is a folder rather than one file, which means it needs a
 * network the first time — so this puts back what the single-file build gave
 * away. Everything the game loads is a static, content-hashed asset, so the
 * strategy is the simplest one that works: serve from the cache when it is
 * there, fall back to the network, and quietly file away whatever comes back.
 *
 * Hand-written rather than generated by a plugin. There are four files to look
 * after and a build-time asset manifest would be more machinery than the whole
 * problem is worth.
 */

const CACHE = 'alpine-carve-v1';

// Only the shell is precached. The hashed JS and CSS get picked up on first
// use, which keeps this file from needing to know their names.
const SHELL = ['./', './index.html', './manifest.webmanifest', './icon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  // Drop caches from older versions, then take over open pages immediately.
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  // Same-origin only: there is nothing else to cache, and proxying anything
  // else would be a surprise.
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    caches.match(request).then((hit) => {
      if (hit) return hit;
      return fetch(request).then((response) => {
        // Opaque and error responses are not worth keeping.
        if (!response || response.status !== 200 || response.type !== 'basic') return response;
        const copy = response.clone();
        caches.open(CACHE).then((cache) => cache.put(request, copy));
        return response;
      });
    })
  );
});
